package owl.nh;

/** Delayed/ignored input scenarios using the production tick, preparation and attack state machines. */
public final class OlmFoundationTests {
 static void check(boolean ok,String text){CoreTests.check(ok,"Olm foundation: "+text);}
 public static void main(String[] args){
  long[] now={1000000000L};CombatCore.TickManager clock=new CombatCore.TickManager(()->now[0]);clock.onTick(1);for(int tick=2;tick<=5;tick++){now[0]+=500000000L;clock.onTick(tick);}check(clock.observedPeriodMs()==500,"observed tick interval replaces initial estimate");now[0]+=100000000L;clock.onTick(5);check(clock.elapsedMs()==100&&clock.remainingMs()==400,"duplicate tick cannot reset phase");now[0]+=900000000L;clock.onTick(7);check(clock.observedPeriodMs()==500,"missed tick events do not double estimated period");
  OlmAttackTiming attacks=new OlmAttackTiming();attacks.reset();attacks.requested(10);check(!attacks.ready(10)&&!attacks.walkingAllowed(10)&&!attacks.walkingAllowed(11),"attack click cannot start a cooldown walking window or cancel itself");check(attacks.ready(12)&&!attacks.walkingAllowed(12),"unconfirmed input times out without inventing an attack");attacks.observed(13,4);check(!attacks.walkingAllowed(13),"no optional movement in the attack's observed tick");check(!attacks.ready(16)&&attacks.walkingAllowed(16)&&attacks.ready(17),"four-tick weapon follows observed attack tick, not earlier click");attacks.requested(17);check(!attacks.walkingAllowed(18),"next input must be acknowledged before optional walking");attacks.observed(18,5);check(!attacks.ready(22)&&attacks.ready(23),"new observed weapon speed replaces prior cooldown");
  preparation();gearSwitch();pacedSwitch();inventoryThenPrayers();
  attacks.reset();attacks.requested(30);attacks.movementInterrupted();check(attacks.ready(30),"movement releases an unconfirmed attack request without a two-tick timeout");attacks.observed(30,4);attacks.requested(31);attacks.movementInterrupted();check(!attacks.ready(31)&&attacks.ready(34),"movement preserves the real confirmed weapon cooldown");
  System.out.println("Olm foundation checks passed: measured/duplicate/missed ticks, request versus observed attack, cancellation prevention, delayed and ignored seven-sip preparation. No live inputs.");
 }
 private static void pacedSwitch(){
  OlmGearBatch batch=new OlmGearBatch();java.util.List<Integer> gear=java.util.Arrays.asList(1,2,3,4,5,6,7,8);java.util.Set<Integer> pending=new java.util.HashSet<>();batch.plan(CombatCore.Style.MAGIC,gear,java.util.Collections.emptySet(),pending);
  check(!batch.allowed(100,250,600),"paced switch waits for an early tick rather than cramming four clicks into its end");
  int submitted=0;for(int tick=101;tick<=102;tick++)for(int slot=0;slot<4;slot++){long elapsed=20+slot*120;batch.plan(CombatCore.Style.MAGIC,gear,java.util.Collections.emptySet(),pending);check(batch.allowed(tick,elapsed,600),"scheduled gear slot available");int item=OlmGearSwitch.next(gear,java.util.Collections.emptySet(),pending);pending.add(item);batch.sent(tick,elapsed,600);submitted++;check(!batch.allowed(tick,elapsed+20,600),"next client cycle cannot burst another gear click");}
  batch.plan(CombatCore.Style.MAGIC,gear,java.util.Collections.emptySet(),pending);check(submitted==8&&batch.prayerPhase(),"eight paced clicks use four slots in each of two actual game ticks");
  batch.plan(CombatCore.Style.MELEE,gear,java.util.Collections.emptySet(),java.util.Collections.emptySet());check(!batch.allowed(102,500,600),"changing style cannot reset the four-item budget inside the same tick");
  batch.reset();batch.plan(CombatCore.Style.MAGIC,gear,java.util.Collections.emptySet(),java.util.Collections.emptySet());check(batch.allowed(110,0,600),"new early transaction starts");batch.sent(110,0,600);check(batch.allowed(110,350,600),"delayed safe action can resume after dodge interruption");batch.sent(110,350,600);check(!batch.allowed(110,370,600)&&!batch.allowed(110,580,600),"interrupted switch neither catches up in a burst nor clicks after its safe window");
 }
 private static void inventoryThenPrayers(){
  java.util.Map<String,Object> fields=new java.util.HashMap<>();fields.put("getVarcIntValue",net.unethicalite.api.widgets.Tab.PRAYER.ordinal());fields.put("getWidget",ChambersTests.fake(net.runelite.api.widgets.Widget.class,java.util.Collections.singletonMap("isVisible",true)));net.runelite.api.Client client=ChambersTests.fake(net.runelite.api.Client.class,fields);
  java.util.List<String> inputs=new java.util.ArrayList<>();int[] cycle={1};VisibleCombatUi ui=new VisibleCombatUi(()->cycle[0],tab->VisibleCombatUi.contentOpen(client,tab),tab->{inputs.add("TAB:"+tab);fields.put("getVarcIntValue",tab.ordinal());});OlmGearBatch batch=new OlmGearBatch();java.util.List<Integer> gear=java.util.Arrays.asList(1,2,3,4,5,6,7,8);java.util.Set<Integer> pending=new java.util.HashSet<>();int prayerRequests=0;
  for(cycle[0]=1;cycle[0]<50&&prayerRequests<2;cycle[0]++){int tick=cycle[0]<20?100:101;batch.plan(CombatCore.Style.MAGIC,gear,java.util.Collections.emptySet(),pending);if(!batch.prayerPhase()){int id=OlmGearSwitch.next(gear,java.util.Collections.emptySet(),pending);if(id>=0&&batch.allowed(tick,400)&&ui.ready(net.unethicalite.api.widgets.Tab.INVENTORY)){check(VisibleCombatUi.contentOpen(client,net.unethicalite.api.widgets.Tab.INVENTORY),"every equipment request requires selected Inventory, despite cached visible prayer widgets");inputs.add("GEAR:"+id);pending.add(id);batch.sent(tick);}}else if(ui.ready(net.unethicalite.api.widgets.Tab.PRAYER)){check(VisibleCombatUi.contentOpen(client,net.unethicalite.api.widgets.Tab.PRAYER),"both prayer requests require selected Prayer book");inputs.add(prayerRequests++==0?"PROTECT_MAGIC":"AUGURY");}}
  java.util.List<String> expected=new java.util.ArrayList<>();expected.add("TAB:INVENTORY");for(int i=1;i<=8;i++)expected.add("GEAR:"+i);expected.add("TAB:PRAYER");expected.add("PROTECT_MAGIC");expected.add("AUGURY");check(inputs.equals(expected),"full sequence is Inventory, eight gear requests across two game ticks, Prayer, protection, boost; no tab oscillation");
 }
 private static void gearSwitch(){
  int[] cycle={200};int tick=40;java.util.List<Integer> required=java.util.Arrays.asList(1,2,3,4,5,6,7,8);java.util.Set<Integer> worn=new java.util.HashSet<>(),pending=new java.util.HashSet<>();java.util.List<Integer> requests=new java.util.ArrayList<>();VisibleCombatUi ui=new VisibleCombatUi(()->cycle[0],tab->true,tab->{});OlmGearBatch batch=new OlmGearBatch();
  batch.plan(CombatCore.Style.MAGIC,required,worn,pending);check(!batch.allowed(tick,100),"late tick cannot start an eight-way batch without enough input budget");
  for(int id:required){batch.plan(CombatCore.Style.MAGIC,required,worn,pending);if(id==5){check(!batch.allowed(tick,300),"fifth request waits for the second actual game tick");tick++;}check(batch.allowed(tick,400),"four requests fit each observed game tick");int next=OlmGearSwitch.next(required,worn,pending);check(next==id&&ui.ready(net.unethicalite.api.widgets.Tab.INVENTORY),"next missing item uses visible Inventory");requests.add(next);pending.add(next);batch.sent(tick);check(!ui.claim(),"same-cycle prayer or equipment cannot overwrite the item");cycle[0]++;}
  batch.plan(CombatCore.Style.MAGIC,required,worn,pending);check(requests.equals(required)&&tick==41&&batch.prayerPhase()&&worn.isEmpty(),"eight requests span exactly two actual ticks, then Prayer may proceed while gear acknowledgement is pending");check(OlmGearSwitch.next(required,worn,pending)==-1&&!worn.containsAll(required),"pending requests are not falsely confirmed as equipment");worn.addAll(required);batch.plan(CombatCore.Style.MAGIC,required,worn,pending);check(batch.stage()==OlmGearBatch.Stage.READY,"actual equipment confirmation completes transaction");
  batch.plan(CombatCore.Style.MELEE,java.util.Arrays.asList(9),worn,pending);check(!batch.prayerPhase(),"style change starts a new Inventory transaction rather than leaking Prayer readiness");
 }
 private static void preparation(){
  OlmStrategy strategy=new OlmStrategy();strategy.reset();OlmPotionFlow potions=new OlmPotionFlow();potions.reset(100);OlmStrategy.View state=OlmStrategyTests.ready();state.entered=false;state.hp=99;state.hpPercent=99;state.entryAvailable=true;int tick=100,doses=20;
  String[] order={"overload","enhance","aid","aid","aid","aid","revitalisation"};
  for(int index=0;index<order.length;index++){
   OlmStrategy.Choice choice=strategy.choose(state);check(choice.kind==OlmStrategy.Kind.DRINK&&choice.value.equals(order[index]),"preparation requests the correct next family at step "+index);check(potions.ready(tick),"only send on observed cooldown availability");potions.requested(choice.value,doses,tick,choice.preparationCredit);
   check(potions.observe(doses,tick+1,3)==OlmPotionFlow.Result.NONE&&strategy.preparationStep()==index&&!potions.ready(tick+1),"unchanged inventory cannot advance preparation or trigger another potion");
   if(index==1){check(potions.observe(doses,tick+5,3)==OlmPotionFlow.Result.TIMED_OUT,"ignored enhance click times out");check(strategy.preparationStep()==index,"ignored click retains preparation step");tick+=6;potions.requested(choice.value,doses,tick,true);}
   check(potions.observe(--doses,tick+2,3)==OlmPotionFlow.Result.CONFIRMED,"delayed consumed dose is confirmed");if(potions.preparationCredit())strategy.drinkConfirmed();check(!potions.ready(tick+4)&&potions.ready(tick+5),"late inventory response shifts the next request, avoiding an early ignored click");tick+=5;
  }
  check(strategy.preparationStep()==7&&strategy.choose(state).kind==OlmStrategy.Kind.ENTER,"entry begins only after all seven doses are actually observed");
 }
}
